import httpx
import json

BASE_URL = "https://www.cloudworldmodel.ai/api"
API_KEY = "your-api-key"
JOB_ID = "job_abc123"

url = f"{BASE_URL}/multi-cloud/jobs/{JOB_ID}/stream"
headers = {"Authorization": f"Bearer {API_KEY}", "Accept": "text/event-stream"}

with httpx.stream("GET", url, headers=headers, timeout=None) as response:
    response.raise_for_status()
    buffer = ""
    for chunk in response.iter_text():
        buffer += chunk
        *frames, buffer = buffer.split("\n\n")
        for frame in frames:
            event_type, data_str = "message", None
            for line in frame.splitlines():
                if line.startswith("event:"):
                    event_type = line[len("event:"):].strip()
                elif line.startswith("data:"):
                    data_str = line[len("data:"):].strip()
            if not data_str:
                continue
            payload = json.loads(data_str)
            if event_type == "progressUpdate":
                print(f"Progress: {payload['progress']}%")
            elif event_type == "strategyGenerated":
                s = payload["strategy"]
                print(f"Strategy: {s['name']}  cost=${s['metrics']['monthlyCost']}/mo")
            elif event_type == "completed":
                top = payload.get("topStrategy", {})
                print(f"Done. Top strategy: {top.get('name')}")
                break

const BASE_URL = "https://www.cloudworldmodel.ai/api";
const API_KEY = "your-api-key";
const JOB_ID = "job_abc123";

const response = await fetch(`${BASE_URL}/multi-cloud/jobs/${JOB_ID}/stream`, {
  headers: { "Authorization": `Bearer ${API_KEY}`, "Accept": "text/event-stream" },
});
if (!response.ok) throw new Error(`HTTP ${response.status}`);

const reader = response.body.getReader();
const decoder = new TextDecoder();
let buffer = "";

while (true) {
  const { value, done } = await reader.read();
  if (done) break;
  buffer += decoder.decode(value, { stream: true });
  const frames = buffer.split(/\n\n/);
  buffer = frames.pop();
  for (const frame of frames) {
    const eventLine = frame.match(/^event:\s*(.+)$/m);
    const dataLine  = frame.match(/^data:\s*(.+)$/m);
    if (!dataLine) continue;
    const eventType = eventLine ? eventLine[1].trim() : "message";
    const payload   = JSON.parse(dataLine[1]);
    if (eventType === "progressUpdate") {
      console.log(`Progress: ${payload.progress}%`);
    } else if (eventType === "strategyGenerated") {
      const s = payload.strategy;
      console.log(`Strategy: ${s.name}  cost=$${s.metrics.monthlyCost}/mo`);
    } else if (eventType === "completed") {
      console.log("Done. Top strategy:", payload.topStrategy?.name);
      reader.cancel();
    }
  }
}

