/**
 * Two-phase training loop: fast warm-up followed by fine-grained training.
 *
 * Phase 1 – Warm-up (300 s ticks)
 *   Use large tick_seconds to fast-forward through startup noise before the
 *   agent starts making meaningful autoscaling decisions. Each step advances
 *   the simulation clock by 5 minutes, so 20 warm-up steps cover ~1.7 hours
 *   of simulated time in seconds of wall time.
 *
 * Phase 2 – Training (60 s ticks)
 *   Switch to 1-minute ticks for precise autoscaling control. The agent now
 *   observes and reacts to traffic on a per-minute basis, matching the
 *   granularity of real autoscaling cooldown windows (e.g. AWS default: 300 s).
 */
const BASE_URL = "https://www.cloudworldmodel.ai/api";
const API_KEY = "your-api-key";
const ENV_ID = "env-aws-001";

async function step(action, tickSeconds) {
  const resp = await fetch(`${BASE_URL}/rl/environments/${ENV_ID}/step`, {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${API_KEY}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ action, tick_seconds: tickSeconds }),
  });
  if (!resp.ok) throw new Error(`step failed: ${resp.status}`);
  return resp.json();
}

const NO_OP = { type: "no_op", parameters: {} };

// --- Phase 1: Warm-up (300 s / 5-minute ticks) ---
const WARMUP_STEPS = 20;
console.log("=== Warm-up phase (300 s ticks) ===");
let data;
for (let i = 0; i < WARMUP_STEPS; i++) {
  data = await step(NO_OP, 300);
  console.log(
    `  warmup ${String(i + 1).padStart(2)}/${WARMUP_STEPS}` +
    `  sim=${data.sim_time_human.padStart(8)}` +
    `  cpu=${(data.obs.cpu_util * 100).toFixed(1)}%` +
    `  instances=${data.obs.instances}`
  );
  if (data.done) {
    console.log("  Episode ended during warm-up — reset and retry.");
    break;
  }
}

// --- Phase 2: Training (60 s / 1-minute ticks) ---
console.log("\n=== Training phase (60 s ticks) ===");
let done = false;
while (!done) {
  const cpu = data.obs.cpu_util;
  let action;
  if (cpu > 0.75) {
    action = { type: "scale_out", parameters: { instanceCount: 1 } };
  } else if (cpu < 0.30 && data.obs.instances > 1) {
    action = { type: "scale_in", parameters: { instanceCount: 1 } };
  } else {
    action = NO_OP;
  }

  data = await step(action, 60);
  done = data.done;
  console.log(
    `  t=${String(data.t).padStart(4)}  sim=${data.sim_time_human.padStart(8)}` +
    `  reward=${data.reward >= 0 ? "+" : ""}${data.reward.toFixed(3)}` +
    `  cpu=${(data.obs.cpu_util * 100).toFixed(1)}%` +
    `  p95=${data.metrics.latency_p95} ms` +
    `  cost=$${data.metrics.cost_usd_hr.toFixed(2)}/hr` +
    `  done=${done}`
  );
}

/**
 * Mid-episode warmup_factor safe-access pattern.
 *
 * obs.warmup_factor is an optional field — it is ABSENT from the observation
 * vector until the first cold compute instance exists in the episode. This
 * happens in two cases:
 *   1. An `add_resource` action provisions a new compute resource mid-episode.
 *   2. Canvas autoscaling adds a compute replica in response to high CPU/traffic.
 *
 * Because the field appears dynamically, agents building a fixed-width
 * observation vector must default to 1.0 (fully warmed) when the field is absent:
 *
 *   const wf = data.obs.warmup_factor ?? 1.0;
 *
 * A value < 1.0 means at least one compute instance is still warming up.
 * Use wf directly as a feature — do not re-derive it from
 * metrics.compute[].warmup_steps_remaining.
 */
const BASE_URL = "https://www.cloudworldmodel.ai/api";
const API_KEY = "your-api-key";
const ENV_ID = "env-aws-001";

async function step(action) {
  const resp = await fetch(`${BASE_URL}/rl/environments/${ENV_ID}/step`, {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${API_KEY}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ action }),
  });
  if (!resp.ok) throw new Error(`step failed: ${resp.status}`);
  return resp.json();
}

let done = false;
let data = await step({ type: "no_op", parameters: {} });
while (!done) {
  // --- build observation vector (always safe even if field absent) ---
  const obs = data.obs;
  const wf = obs.warmup_factor ?? 1.0;  // 1.0 = fully warmed / no cold instance

  const cpu = obs.cpu_util;
  // penalise decisions made while a cold instance is still warming up
  const effectiveCpu = wf > 0 ? cpu / wf : cpu;

  let action;
  if (effectiveCpu > 0.75) {
    action = { type: "scale_out", parameters: { instanceCount: 1 } };
  } else if (effectiveCpu < 0.30 && obs.instances > 1) {
    action = { type: "scale_in", parameters: { instanceCount: 1 } };
  } else {
    action = { type: "no_op", parameters: {} };
  }

  data = await step(action);
  done = data.done;
  console.log(
    `  t=${String(data.t).padStart(4)}  wf=${wf.toFixed(2)}` +
    `  cpu=${(cpu * 100).toFixed(1)}%  effectiveCpu=${(effectiveCpu * 100).toFixed(1)}%` +
    `  reward=${data.reward >= 0 ? "+" : ""}${data.reward.toFixed(3)}  done=${done}`
  );
}

